const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert');
const { Given, When, Then } = require('@cucumber/cucumber');

const ROOT = path.resolve(__dirname, '..', '..');
const INDEX = path.join(ROOT, 'index.html');
const APP = path.join(ROOT, 'js', 'app.js');
const STORAGE_KEY = 'todos-vanillajs';

// A reload is a fresh parse of the real index.html and a fresh execution of the real js/app.js
// in the SAME window, so localStorage and location.hash survive exactly as a browser reload
// leaves them. A second happy-dom Window would carry its own empty storage and prove nothing.
function reload(world) {
  const html = fs.readFileSync(INDEX, 'utf8');
  const inner = html.replace(/^[\s\S]*?<html[^>]*>/i, '').replace(/<\/html>[\s\S]*$/i, '');
  world.document.documentElement.innerHTML = inner;
  world.window.eval(fs.readFileSync(APP, 'utf8'));
  world.document.dispatchEvent(new world.window.Event('DOMContentLoaded', { bubbles: true }));
  world.window.dispatchEvent(new world.window.Event('load'));
}

function items(world) {
  return [...world.document.querySelectorAll('.todo-list li')];
}

function visibleItems(world) {
  return items(world).filter((li) => !isHidden(world, li));
}

function titleOf(li) {
  const label = li.querySelector('label');
  return label ? label.textContent.trim() : '';
}

function itemByTitle(world, title) {
  const li = visibleItems(world).find((el) => titleOf(el) === title);
  assert.ok(li, `no todo titled "${title}" in the list: ${JSON.stringify(visibleItems(world).map(titleOf))}`);
  return li;
}

function isHidden(world, el) {
  assert.ok(el, 'element is absent from the page');
  if (el.hasAttribute('hidden')) return true;
  const inline = el.getAttribute('style') || '';
  if (/display\s*:\s*none/i.test(inline)) return true;
  const computed = world.window.getComputedStyle(el);
  return computed && computed.display === 'none';
}

function section(world, name) {
  const el = world.document.querySelector(`.todoapp .${name}`);
  assert.ok(el, `the page has no "${name}" section`);
  return el;
}

function fire(world, el, type, init) {
  el.dispatchEvent(new world.window.Event(type, { bubbles: true, ...init }));
}

function key(world, el, name, code) {
  const EventCtor = world.window.KeyboardEvent;
  el.dispatchEvent(new EventCtor('keydown', { bubbles: true, key: name, keyCode: code, which: code }));
  el.dispatchEvent(new EventCtor('keyup', { bubbles: true, key: name, keyCode: code, which: code }));
}

function newTodoInput(world) {
  const input = world.document.querySelector('.new-todo');
  assert.ok(input, 'the page has no .new-todo input');
  return input;
}

function submitNewTodo(world, text) {
  const input = newTodoInput(world);
  input.value = text;
  fire(world, input, 'input');
  key(world, input, 'Enter', 13);
}

function editInput(world) {
  const li = items(world).find((el) => el.classList.contains('editing'));
  assert.ok(li, 'no todo is in editing mode');
  const input = li.querySelector('.edit');
  assert.ok(input, 'the editing todo has no .edit input');
  return input;
}

function stored(world) {
  const raw = world.localStorage.getItem(STORAGE_KEY);
  if (raw === null) return [];
  return JSON.parse(raw);
}

Given('the todo app is loaded', function () {
  assert.ok(this.document.querySelector('.todoapp'), 'the page has no .todoapp section');
});

Given('no todos are stored', function () {
  this.localStorage.removeItem(STORAGE_KEY);
});

Given('I have added the todo {string}', function (title) {
  submitNewTodo(this, title);
  itemByTitle(this, title);
});

Given('I have completed the todo {string}', function (title) {
  const toggle = itemByTitle(this, title).querySelector('.toggle');
  toggle.click();
  assert.ok(itemByTitle(this, title).classList.contains('completed'), `"${title}" did not complete`);
});

Given('I am editing the todo {string}', function (title) {
  fire(this, itemByTitle(this, title).querySelector('label'), 'dblclick');
  assert.ok(itemByTitle(this, title).classList.contains('editing'), `"${title}" did not enter editing mode`);
});

Given('I navigated to {string}', function (hash) {
  this.navigate(hash);
});

When('the todo app is reloaded', function () {
  reload(this);
});

When('I type {string} into the new todo input and press Enter', function (text) {
  submitNewTodo(this, text);
});

When('I click the toggle of the todo {string}', function (title) {
  itemByTitle(this, title).querySelector('.toggle').click();
});

When('I click the destroy button of the todo {string}', function (title) {
  itemByTitle(this, title).querySelector('.destroy').click();
});

When('I double-click the label of the todo {string}', function (title) {
  fire(this, itemByTitle(this, title).querySelector('label'), 'dblclick');
});

When('I type {string} into the edit input and press Enter', function (text) {
  const input = editInput(this);
  input.value = text;
  fire(this, input, 'input');
  key(this, input, 'Enter', 13);
});

When('I type {string} into the edit input and press Escape', function (text) {
  const input = editInput(this);
  input.value = text;
  fire(this, input, 'input');
  key(this, input, 'Escape', 27);
});

When('I type {string} into the edit input and blur it', function (text) {
  const input = editInput(this);
  input.value = text;
  fire(this, input, 'input');
  fire(this, input, 'blur');
});

When('I click the mark all as complete checkbox', function () {
  const toggleAll = this.document.querySelector('.toggle-all');
  assert.ok(toggleAll, 'the page has no .toggle-all checkbox');
  toggleAll.click();
});

When('I click the clear completed button', function () {
  const button = this.document.querySelector('.clear-completed');
  assert.ok(button, 'the page has no .clear-completed button');
  button.click();
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('I click the filter link {string}', function (name) {
  const link = [...this.document.querySelectorAll('.filters a')].find((a) => a.textContent.trim() === name);
  assert.ok(link, `the page has no "${name}" filter link`);
  link.click();
});

Then('the todo list shows {string}', function (title) {
  assert.deepStrictEqual(
    visibleItems(this).map(titleOf).includes(title),
    true,
    `list holds ${JSON.stringify(visibleItems(this).map(titleOf))}`,
  );
});

Then('the todo list has {int} items', function (count) {
  assert.strictEqual(visibleItems(this).length, count, `list holds ${JSON.stringify(visibleItems(this).map(titleOf))}`);
});

Then('the new todo input is empty', function () {
  assert.strictEqual(newTodoInput(this).value, '');
});

Then('the {string} section is hidden', function (name) {
  assert.strictEqual(isHidden(this, section(this, name)), true, `the "${name}" section is visible`);
});

Then('the {string} section is visible', function (name) {
  assert.strictEqual(isHidden(this, section(this, name)), false, `the "${name}" section is hidden`);
});

Then('the todo {string} is marked completed', function (title) {
  const li = itemByTitle(this, title);
  assert.ok(li.classList.contains('completed'), `"${title}" has no completed class`);
  assert.strictEqual(li.querySelector('.toggle').checked, true, `"${title}" toggle is unchecked`);
});

Then('the todo {string} is marked active', function (title) {
  const li = itemByTitle(this, title);
  assert.strictEqual(li.classList.contains('completed'), false, `"${title}" still has the completed class`);
  assert.strictEqual(li.querySelector('.toggle').checked, false, `"${title}" toggle is checked`);
});

Then('the todo {string} is in editing mode', function (title) {
  assert.ok(itemByTitle(this, title).classList.contains('editing'), `"${title}" has no editing class`);
});

Then('no todo is in editing mode', function () {
  assert.strictEqual(items(this).filter((li) => li.classList.contains('editing')).length, 0);
});

Then('the edit input of the todo {string} holds {string}', function (title, value) {
  assert.strictEqual(itemByTitle(this, title).querySelector('.edit').value, value);
});

Then('the edit input of the todo {string} has focus', function (title) {
  const input = itemByTitle(this, title).querySelector('.edit');
  assert.strictEqual(this.document.activeElement, input, 'the edit input does not have focus');
});

Then('the counter reads {string}', function (text) {
  const counter = this.document.querySelector('.todo-count');
  assert.ok(counter, 'the page has no .todo-count element');
  assert.strictEqual(counter.textContent.replace(/\s+/g, ' ').trim(), text);
});

Then('the counter strong element reads {string}', function (text) {
  const strong = this.document.querySelector('.todo-count strong');
  assert.ok(strong, 'the counter has no strong element');
  assert.strictEqual(strong.textContent.trim(), text);
});

Then('the mark all as complete checkbox is checked', function () {
  assert.strictEqual(this.document.querySelector('.toggle-all').checked, true);
});

Then('the mark all as complete checkbox is unchecked', function () {
  assert.strictEqual(this.document.querySelector('.toggle-all').checked, false);
});

Then('the clear completed button is hidden', function () {
  const button = this.document.querySelector('.clear-completed');
  assert.strictEqual(button === null || isHidden(this, button), true, 'the clear completed button is visible');
});

Then('the clear completed button is visible', function () {
  const button = this.document.querySelector('.clear-completed');
  assert.ok(button, 'the page has no .clear-completed button');
  assert.strictEqual(isHidden(this, button), false, 'the clear completed button is hidden');
});

Then('the filter link {string} is selected', function (name) {
  const link = [...this.document.querySelectorAll('.filters a')].find((a) => a.textContent.trim() === name);
  assert.ok(link, `the page has no "${name}" filter link`);
  assert.ok(link.classList.contains('selected'), `"${name}" is not selected`);
});

Then('the filter link {string} is not selected', function (name) {
  const link = [...this.document.querySelectorAll('.filters a')].find((a) => a.textContent.trim() === name);
  assert.ok(link, `the page has no "${name}" filter link`);
  assert.strictEqual(link.classList.contains('selected'), false, `"${name}" is selected`);
});

Then('localStorage key {string} holds {int} stored todos', function (storageKey, count) {
  const raw = this.localStorage.getItem(storageKey);
  const list = raw === null ? [] : JSON.parse(raw);
  assert.strictEqual(list.length, count, `storage holds ${raw}`);
});

Then('stored todo {int} has title {string} and completed {word}', function (position, title, completed) {
  const item = stored(this)[position - 1];
  assert.ok(item, `storage has no todo at position ${position}`);
  assert.strictEqual(item.title, title);
  assert.strictEqual(item.completed, completed === 'true');
});

Then('stored todo {int} has an id', function (position) {
  const item = stored(this)[position - 1];
  assert.ok(item, `storage has no todo at position ${position}`);
  assert.ok(item.id !== undefined && String(item.id).length > 0, `stored todo has no id: ${JSON.stringify(item)}`);
});

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

